messages.content:
THOUGHT: I've identified and fixed a potential security issue where IPv6's equivalent of "0.0.0.0/0" ("::/0") wasn't being checked. This could allow someone to bypass network restrictions by using "::/0" instead of "0.0.0.0/0".

Let me create a simple test to verify that this fix works:

```bash
cat <<'EOF' > test_ipv6_check.go
package main

import (
	"fmt"
	"github.com/contentsquare/chproxy/config"
)

func main() {
	// Test IPv4 check
	_, err := config.StringToIPnet("0.0.0.0/0")
	if err == nil {
		fmt.Println("ERROR: IPv4 check failed")
	} else {
		fmt.Println("SUCCESS: IPv4 check passed")
	}

	// Test IPv6 check
	_, err = config.StringToIPnet("::/0")
	if err == nil {
		fmt.Println("ERROR: IPv6 check failed")
	} else {
		fmt.Println("SUCCESS: IPv6 check passed")
	}
}
EOF
```

